      n: n,
      linhas: ls,
      txt:
        'Lista de compra · pré-graduados · ' +
        ('0' + d.getDate()).slice(-2) +
        '/' +
        ('0' + (d.getMonth() + 1)).slice(-2) +
        '\n' +
        ls.join('\n') +
        '\nTotal: ' +
        n +
        ' peças'
