      ttl.style.fontSize = '16px';
      c.appendChild(ttl);
      var dsc = S.desc[i.ref] != null ? S.desc[i.ref] : autoDesc(i.ref);
      var dt = mk('div', '', dsc || 'Sem descrição ainda.');
      dt.style.cssText = 'font-size:14px;line-height:1.45;' + (dsc ? '' : 'color:var(--mute)');
