    var cab = mk('div', 'nav');
    MOEDAS3.forEach(function (o) {
      cab.appendChild(
        btn(
          'chip' + (x.m === o[0] ? ' on' : ''),
          o[1],
          function () {
            x.m = o[0];
            x.r = '';
            pmRender(true);
            pmMudou();
          },
          x.m === o[0]
        )
      );
    });
