    au.id = 'nvAuto';
    au.hidden = true;
    s1.appendChild(au);
    var mais = document.createElement('details');
    mais.id = 'nvMais';
    mais.innerHTML = '<summary class="lbl" style="cursor:pointer;margin:0">Mais detalhes (opcional)</summary><div class="col" id="nvMaisBox" style="gap:12px;margin-top:10px"></div>';
    s1.appendChild(mais);
    var mb = $('nvMaisBox');
