    mb.appendChild($('eBox').querySelector('.descp'));
    mb.appendChild($('eFaixaB'));
    mb.appendChild(lt);
    var nx = btn('go', 'Continuar para cores e fotos', function () {
      nvContinuar();
    });
    nx.id = 'nvNext';
