    // liberar para o site
    var c2 = mk('div', 'card col');
    c2.style.gap = '10px';
    var lh = mk('div', '');
    lh.style.cssText = 'display:flex;justify-content:space-between;align-items:center;gap:10px';
    lh.appendChild(mk('b', '', 'Liberar para o site'));
    var on = siteOn(ref),
      tg = mk('button', 'nvtg' + (on ? ' on' : ''));
