            var dels = [nvApi('DELETE', 'produtos/' + ref).catch(function () {})];
            for (var k = 0; k < 8; k++) dels.push(nvApi('DELETE', 'fotos/' + ref + (k ? '~' + k : '')).catch(function () {}));
